                                                                                                                                                                                                             
  CREATE TABLE "CODE_SYSTEM"                                                                                                                                                                      
   (	"SYSTEM_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"SYSTEM_NAME" NVARCHAR2(64),                                                                                                                                                                                
	"SYSTEM_CODE" NVARCHAR2(32),                                                                                                                                                                                
	"REMARK" NVARCHAR2(255),                                                                                                                                                                                    
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                         
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"CREATION_DATE" DATE,                                                                                                                                                                                       
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                  
	"UPDATED_DATE" DATE,                                                                                                                                                                                        
	"IS_ENABLE" NUMBER(1,0),                                                                                                                                                                                    
	"DEL_FLAG" NUMBER(1,0),                                                                                                                                                                                     
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                               
	 PRIMARY KEY ("SYSTEM_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                        
   ) ;                                                                                                                                                                                                       

